-- ShopEase / MySQL 8+ or MariaDB 10.6+ / InnoDB / IDR
CREATE DATABASE IF NOT EXISTS db_shopease CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE db_shopease;
CREATE TABLE IF NOT EXISTS users (
    id_user INT AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    email VARCHAR(100) NOT NULL UNIQUE,
    password VARCHAR(255) NOT NULL,
    role ENUM('customer', 'admin', 'operator') NOT NULL DEFAULT 'customer',
    phone VARCHAR(20),
    address TEXT,
    created_at DATETIME NULL,
    updated_at DATETIME NULL
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS categories(id VARCHAR(40) PRIMARY KEY,name VARCHAR(100) NOT NULL,slug VARCHAR(150) NOT NULL UNIQUE,description TEXT,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS products(id VARCHAR(40) PRIMARY KEY,category_id VARCHAR(40) NOT NULL,name VARCHAR(150) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,description TEXT NOT NULL,price DECIMAL(12,2) NOT NULL,old_price DECIMAL(12,2) NOT NULL,stock INT NOT NULL,image VARCHAR(255) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'active',sold INT NOT NULL DEFAULT 0,rating VARCHAR(5) NOT NULL DEFAULT '4.9',created_at VARCHAR(30) NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id),CHECK(stock>=0),CHECK(price>=0),INDEX idx_category_status(category_id,status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS carts(id VARCHAR(60) PRIMARY KEY,user_id INT NOT NULL UNIQUE,FOREIGN KEY(user_id) REFERENCES users(id_user)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS cart_items(id VARCHAR(40) PRIMARY KEY,cart_id VARCHAR(60) NOT NULL,product_id VARCHAR(40) NOT NULL,quantity INT NOT NULL,CHECK(quantity>0),UNIQUE KEY cart_product(cart_id,product_id),FOREIGN KEY(cart_id) REFERENCES carts(id),FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS addresses(id VARCHAR(40) PRIMARY KEY,user_id INT NOT NULL,recipient_name VARCHAR(100) NOT NULL,phone VARCHAR(25) NOT NULL,address TEXT NOT NULL,city VARCHAR(100) NOT NULL,province VARCHAR(100) NOT NULL,postal_code VARCHAR(5) NOT NULL,is_default TINYINT NOT NULL DEFAULT 0,FOREIGN KEY(user_id) REFERENCES users(id_user)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS orders(id VARCHAR(40) PRIMARY KEY,user_id INT NOT NULL,address_id VARCHAR(40) NOT NULL,order_number VARCHAR(50) NOT NULL UNIQUE,subtotal DECIMAL(12,2) NOT NULL,shipping_cost DECIMAL(12,2) NOT NULL,total DECIMAL(12,2) NOT NULL,order_status VARCHAR(30) NOT NULL DEFAULT 'pending_payment',notes TEXT NOT NULL,created_at VARCHAR(30) NOT NULL,idempotency_key VARCHAR(100) NOT NULL UNIQUE,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id_user),FOREIGN KEY(address_id) REFERENCES addresses(id),INDEX idx_orders_user(user_id,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_items(id VARCHAR(40) PRIMARY KEY,order_id VARCHAR(40) NOT NULL,product_id VARCHAR(40) NULL,product_name VARCHAR(150) NOT NULL,price DECIMAL(12,2) NOT NULL,quantity INT NOT NULL,subtotal DECIMAL(12,2) NOT NULL,CHECK(quantity>0),FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payments(id VARCHAR(40) PRIMARY KEY,order_id VARCHAR(40) NOT NULL UNIQUE,method VARCHAR(50) NOT NULL DEFAULT 'Transfer manual',amount DECIMAL(12,2) NOT NULL,proof_file VARCHAR(255),sender_name VARCHAR(100),payment_status VARCHAR(20) NOT NULL DEFAULT 'unpaid',verified_by INT,verified_at VARCHAR(30),reason TEXT,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(verified_by) REFERENCES users(id_user)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS shipments(id VARCHAR(40) PRIMARY KEY,order_id VARCHAR(40) NOT NULL UNIQUE,courier VARCHAR(100),tracking_number VARCHAR(100),shipment_status VARCHAR(20) NOT NULL DEFAULT 'pending',shipped_at VARCHAR(30),delivered_at VARCHAR(30),FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit(id VARCHAR(40) PRIMARY KEY,user_id INT NOT NULL,order_id VARCHAR(40) NOT NULL,action VARCHAR(1000) NOT NULL,created_at VARCHAR(30) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id_user),FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS contacts(id VARCHAR(40) PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL,message TEXT NOT NULL,created_at VARCHAR(30) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS attempts(id VARCHAR(64) PRIMARY KEY,count INT NOT NULL,expires BIGINT NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS karyawan(id_karyawan INT AUTO_INCREMENT PRIMARY KEY,nip VARCHAR(20) NOT NULL UNIQUE,nama VARCHAR(100) NOT NULL,jabatan VARCHAR(50) NOT NULL,email VARCHAR(100) NOT NULL UNIQUE,telepon VARCHAR(20) NOT NULL,alamat TEXT,tanggal_masuk DATE NOT NULL,status VARCHAR(10) NOT NULL DEFAULT 'aktif',created_at DATETIME NULL,updated_at DATETIME NULL) ENGINE=InnoDB;
